import json, math
from pathlib import Path
import nbformat
import matplotlib
matplotlib.use('Agg')

ns = {}
# provide display for plain exec
try:
    from IPython.display import display
except Exception:
    def display(*args, **kwargs):
        return None
ns['display'] = display

nb = nbformat.read('modelo_medicina.ipynb', as_version=4)
for i, cell in enumerate(nb.cells):
    if cell.cell_type == 'code':
        code = cell.source
        try:
            exec(compile(code, f'modelo_medicina.ipynb:cell_{i}', 'exec'), ns)
        except Exception as e:
            raise RuntimeError(f'Error executing cell {i}: {e}') from e

summary_path = Path('validation_results.json')
summary = json.loads(summary_path.read_text())

def rec_from_df(df, key_col):
    if df is None or len(df) == 0:
        return None
    row = df.iloc[0]
    return {
        'grupo': str(row[key_col]),
        'n': int(row['n']),
        'MAE': float(row['MAE']),
        'RMSE': float(row['RMSE']),
        'sesgo_medio': float(row['sesgo_medio']),
        'grupo_confiable': bool(row['grupo_confiable']),
    }

def top_confiable(df, key_col):
    reliable = df[df['grupo_confiable']].copy()
    if reliable.empty:
        return None
    return rec_from_df(reliable.sort_values('MAE', ascending=False), key_col)

resumen_residuos = ns['resumen_residuos']
residuo_test = resumen_residuos[resumen_residuos['split'].eq('test')].iloc[0]
residuo_valid = resumen_residuos[resumen_residuos['split'].eq('validacion')].iloc[0]

summary.update({
    'model_validation_analysis': 'OK',
    'validation_stage_best_model': str(ns['mejor_modelo_nombre']),
    'prediction_rows': {
        'validation': int(len(ns['validacion_predicciones'])),
        'test': int(len(ns['test_predicciones'])),
    },
    'residual_summary': {
        'validation_residual_mean': float(residuo_valid['residuo_medio']),
        'validation_residual_median': float(residuo_valid['residuo_mediano']),
        'test_residual_mean': float(residuo_test['residuo_medio']),
        'test_residual_median': float(residuo_test['residuo_mediano']),
    },
    'generalization_check': {
        'best_model': str(ns['mejor_modelo_nombre']),
        'mae_gap_validation_minus_train': float(ns['brecha_mae_validacion_train']),
        'mae_gap_test_minus_train': float(ns['brecha_mae_test_train']),
        'mae_gap_test_minus_validation': float(ns['brecha_mae_test_validacion']),
        'test_mae_improvement_vs_baseline': float(ns['mejora_vs_baseline_test']),
    },
    'group_error_threshold_min_n': int(ns['MIN_GRUPO_VALIDACION']),
    'largest_reliable_error_groups_test': {
        'region': top_confiable(ns['analisis_region_test'], 'NOMBRE_REGION'),
        'department': top_confiable(ns['analisis_departamento_test'], 'NOMBRE_DEPARTAMENTO'),
        'institution': top_confiable(ns['analisis_institucion_test'], 'NOMBRE_INSTITUCION'),
        'academic_program': top_confiable(ns['analisis_programa_test'], 'NOMBRE_PROGRAMA_ACAD'),
    },
    'model_validation_conclusion': {
        'generalizes_reasonably': True,
        'reason': 'Test MAE is close to validation MAE and both clearly improve over the baseline.',
        'main_limitation': 'cantidad_evaluados_* are same-period operational variables; remove them if prediction must happen before evaluated counts are known.',
    },
})

summary_path.write_text(json.dumps(summary, indent=2, ensure_ascii=False) + '\n')
print('UPDATED_VALIDATION_RESULTS')
print(json.dumps(summary['largest_reliable_error_groups_test'], indent=2, ensure_ascii=False))
